                المرافق
              </label>
              <div className="flex flex-wrap gap-2">
                {PRIORITY_FACILITIES.map((facility) => (
                  <Badge
                    key={facility}
                    variant={
                      selectedFacilities.includes(facility)
                        ? "default"
                        : "outline"
                    }
                    className="cursor-pointer"
                    onClick={() => toggleFacility(facility)}
                  >
                    {facility}
                  </Badge>
                ))}
              </div>
            </div>

            {/* Buttons */}
            <div className="flex gap-3 mt-6">
              <Button
                variant="outline"
                className="flex-1"
                onClick={() => {
                  clearFilters();
                  setShowFiltersModal(false);
                }}
              >
                مسح الكل
              </Button>

              <Button
                className="flex-1 bg-[#b88d2b] hover:bg-[#a07c25] text-white"
                onClick={() => setShowFiltersModal(false)}
              >
                تطبيق الفلاتر
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </Dialog>
      {/* Image Modal */}
      <Dialog
        open={!!selectedImage}
        onOpenChange={() => setSelectedImage(null)}
      >
        <DialogContent className="max-w-4xl p-0">
          {selectedImage && (
            <div className="relative">
              <DialogTitle className="sr-only">صورة العقار</DialogTitle>
              <img
                src={selectedImage.url}
                alt="صورة العقار"
                className="w-full h-auto rounded-lg"
              />
              <div className="absolute bottom-4 right-4 bg-black/70 text-white px-3 py-1 rounded">
                {selectedImage.index + 1} / {selectedImage.total}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

