                </div>

                {/* شبكة المرافق */}
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                  {FACILITIES
                    .filter(f =>
                      f.toLowerCase().includes(facilitySearch.toLowerCase())
