                        </label>
                      </div>
                    ))}
                </div>

              </div>
            </div>

            <Button
              type="submit"
              className="w-full gradient-golden"
              disabled={isSubmitting}
              data-testid="button-register"
            >
              {isSubmitting ? 'جاري التسجيل...' : 'تسجيل العقار'}
            </Button>
          </form>
        </Card>
      </div>
    </div>
  );
}

